it('should use exponential backoff', async () => {
  const delays: number[] = [];
  let callCount = 0;
  const fn = vi.fn(async () => {
    callCount++;
    if (callCount < 3) {
      throw new Error('Retry me');
    }
    return 'success';
  });

  const startTime = Date.now();
  await withRetry(fn, 3, 100); // base delay 100ms
  const totalTime = Date.now() - startTime;

  // Should have delays of ~100ms (attempt 1) + ~200ms (attempt 2) = 300ms
  // With jitter (0-100ms), total should be between 300-500ms
  expect(totalTime).toBeGreaterThanOrEqual(300);
  expect(totalTime).toBeLessThan(600); // accounting for jitter
});

